onRoleReachedMoon = function()     game.pauseLogic()	if global.getBool("lvl60_b1") then dialog.setSkipEnabled(true) end		repeat			sound.play("54-1");		    if dialog.show("Level60-1", faceWeixiao) ==1 then break end			if dialog.show("Level60-2", faceManyi) ==1 then break end			if dialog.show("Level60-3", faceDeyi) ==1 then break end			if dialog.show("Level60-4", faceRenzhen) ==1 then break end		    if dialog.show("Level60-5", faceManyi) ==1 then break end			sound.play("52-1");			if dialog.show("Level60-6", faceShijin) ==1 then break end			global.setBool("lvl60_b1")		until true		dialog.setSkipEnabled(false)    game.success()end